%[text] %[text:anchor:H_BD68D2C9] # **Generation of one-dimensional mesh along line**
%[text] It returns an one-dimensional linear two-noded mesh along a line:
%[text]{"align":"center"} ![map_to_biunit_domain_linear.png](text:image:5cb7)
%[text:tableOfContents]{"heading":"**Table of Contents**"}
function msh = generateLinearMeshOnLine(X0, XL, numElements)
%[text] %[text:anchor:H_D4260F35] ## **Function Description**
%[text] Returns a structure containing the nodes and the elements on a line corresponding to a linear two-noded mesh.
%[text]  **Input :**
%[text]             X0,XL : The end points of the one-dimensional domain
%[text] numElements : Number of nodes in the one-dimensional mesh
%[text]  **Output :**
%[text]                msh : The one-dimensional mesh using two-noded elements as a structure with the following fields:
%[text]                             .nodes : Number of nodes in the one-dimensional mesh
%[text]                        .elements : Number of elements in the one-dimensional mesh
%[text] %[text:anchor:H_68F5CD34] ## **Function Implementation**
%[text] %[text:anchor:H_81AB7493] ### Input validation
    arguments
        X0 (1, 1) double
        XL (1, 1) double
        numElements (1, 1) double {mustBeInteger, mustBeGreaterThanOrEqual(numElements, 1)}
    end
%[text] %[text:anchor:H_B7F6C29A] ### Mesh generation
    msh.nodes = linspace(X0, XL, numElements + 1)';
    msh.elements = zeros(numElements, 2);
    for ii = 1:numel(msh.elements(:, 1))
        msh.elements(ii, :) = [ii ii + 1];
    end
%[text] 
end

